[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);
\coordinate (Ap) at (0,3.35);
\coordinate (Lp) at (-1.0,0);
\coordinate (Rp) at (1.0,0);
\draw (Lp) arc (180:360:1.0 and 0.32);
\draw[dashed] (Rp) arc (0:180:1.0 and 0.32);
\draw (Ap) -- (Rp) node[midway,right] {$7\text{ cm}$};
\draw (Ap) -- (Lp);
\draw[dashed] (Ap) -- (O);
\draw (O) -- (Rp) node[midway,below] {$2\text{ cm}$};
\coordinate (ra) at ($(O)!0.28cm!(Ap)$);
\coordinate (rb) at ($(O)!0.28cm!(Rp)$);
\draw (ra) -- ($(ra)+(rb)-(O)$) -- (rb);
\fill (O) circle (1.2pt);
\end{tikzpicture}
[/tikz]
Find the surface area of a cone with radius $2\text{ cm}$ and slant height $7\text{ cm}$ in exact form, in terms of $\pi$.

